sys_ui_action.script:
function printForm() {
    // must be a saved record
    var id =  g_form.getUniqueValue();
	// || g_form.getValue('sys_id') || g_form.getParameter('sys_id');
	//g_form.getUniqueValue();
    if (!id) {
        // Optional: prompt to save first
        alert('Please save the record before printing.');
        return;
    }
    alert(' before id is : '+id);
    var url = '/' + g_form.getTableName() + '.do?sys_id=' + id + '&sysparm_view=printable';

   //alert(' after id is : '+id);
   //alert(' url is : '+url);

    window.open(url, '_blank');
    //g_form.print();
    //alert('After Print Please save the record before printing.');
}

